        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find separator value S (value that appears in full rows/columns of separators)
    S = None
    # Check rows
    for r in range(rows):
        if all(grid[r][c] == grid[r][0] for c in range(cols)):
            if len(set(grid[r])) == 1:
                S = grid[r][0]
                break

    if S is None:
        # Check columns
        for c in range(cols):
            col_vals = [grid[r][c] for r in range(rows)]
            if all(v == col_vals[0] for v in col_vals):
                if len(set(col_vals)) == 1:
                    S = col_vals[0]
                    break

    if S is None:
        return grid

    # Determine cell dimensions
    cell_h = 0
    for r in range(rows):
        if all(grid[r][c] == S for c in range(cols)):
            cell_h = r
            break

    cell_w = 0
    for c in range(cols):
        if all(grid[r][c] == S for r in range(rows)):
            cell_w = c
            break

    if cell_h == 0 or cell_w == 0:
        return grid

    # Calculate number of cells
    n_cells_h = (rows + 1) // (cell_h + 1)
    n_cells_w = (cols + 1) // (cell_w + 1)

    # Extract cell values (take top-left of each cell)
    cells = []
    for i in range(n_cells_h):
        row = []
        r = i * (cell_h + 1)
        for j in range(n_cells_w):
            c = j * (cell_w + 1)
            row.append(grid[r][c])
        cells.append(row)

    # Find unique non-zero values (excluding separator)
    unique_vals = set()
    for i in range(n_cells_h):
        for j in range(n_cells_w):
            v = cells[i][j]
            if v != 0 and v != S:
                unique_vals.add(v)

    if len(unique_vals) < 2:
        # Just return original
        return grid

    # Determine neighbor relationships
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    val_to_neighbors = {v: set() for v in unique_vals}

    for i in range(n_cells_h):
        for j in range(n_cells_w):
            v = cells[i][j]
            if v not in unique_vals:
                continue
            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < n_cells_h and 0 <= nj < n_cells_w:
                    nv = cells[ni][nj]
                    if nv != 0 and nv != S and nv != v:
                        val_to_neighbors[v].add(nv)

    # Determine F (fill value) and C (center values)
    # F is the value that appears most often as a neighbor of other values
    neighbor_score = {v: 0 for v in unique_vals}
    for v in unique_vals:
        for u in unique_vals:
            if u != v:
                if v in val_to_neighbors[u]:
                    neighbor_score[v] += 1

    max_score = max(neighbor_score.values())
    candidates_F = [v for v, s in neighbor_score.items() if s == max_score]

    if len(candidates_F) == 1:
        F = candidates_F[0]
    else:
        # Tie-break by frequency: F is the more frequent value
        freq = {v: 0 for v in unique_vals}
        for i in range(n_cells_h):
            for j in range(n_cells_w):
                if cells[i][j] in unique_vals:
                    freq[cells[i][j]] += 1
        F = max(candidates_F, key=lambda x: freq[x])

    C = unique_vals - {F}

    # Apply transformation: neighbors of C become F
    new_cells = [row[:] for row in cells]
    for i in range(n_cells_h):
        for j in range(n_cells_w):
            if cells[i][j] in C:
                for di, dj in directions:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n_cells_h and 0 <= nj < n_cells_w:
                        new_cells[ni][nj] = F

    # Reconstruct grid
    result = [[S for _ in range(cols)] for _ in range(rows)]

    # Fill cells
    for i in range(n_cells_h):
        r_start = i * (cell_h + 1)
        for j in range(n_cells_w):
            c_start = j * (cell_w + 1)
            val = new_cells[i][j]
            for dr in range(cell_h):
                for dc in range(cell_w):
                    if r_start + dr < rows and c_start + dc < cols:
                        result[r_start + dr][c_start + dc] = val

